class Solution {
  public int longestSubarray(int[] nums) {
    int n = nums.length;
    int[] left = new int[n], right = new int[n];
    for (int i = 0; i < n; i++) left[i] = i > 0 && nums[i] >= nums[i - 1] ? left[i - 1] + 1 : 1;
    for (int i = n - 1; i >= 0; i--)
      right[i] = i + 1 < n && nums[i] <= nums[i + 1] ? right[i + 1] + 1 : 1;
    int best = 1;
    for (int i = 0; i < n; i++) {
      best = Math.max(best, left[i]);
      if (i > 0) best = Math.max(best, left[i - 1] + 1);
      if (i + 1 < n) best = Math.max(best, right[i + 1] + 1);
      if (i > 0 && i + 1 < n && nums[i - 1] <= nums[i + 1])
        best = Math.max(best, left[i - 1] + right[i + 1] + 1);
    }
    return best;
  }
}
